## 📚 Context and Examples

**TOTP Implementation:**
```csharp
using OtpNet;

public class TotpService
{
    public string GenerateSecret()
    {
        var key = KeyGeneration.GenerateRandomKey(20);
        return Base32Encoding.ToString(key);
    }

    public string GenerateQrCodeUrl(string secret, string email)
    {
        var issuer = "GameGuild";
        var label = $"{issuer}:{email}";
        var uri = $"otpauth://totp/{Uri.EscapeDataString(label)}" +
                  $"?secret={secret}" +
                  $"&issuer={Uri.EscapeDataString(issuer)}" +
                  $"&algorithm=SHA1" +
                  $"&digits=6" +
                  $"&period=30";

        return $"https://chart.googleapis.com/chart?" +
               $"chs=200x200&chld=M|0&cht=qr&chl={Uri.EscapeDataString(uri)}";
    }

    public bool VerifyCode(string secret, string code)
    {
        var totp = new Totp(Base32Encoding.ToBytes(secret));
        return totp.VerifyTotp(code, out long timeStepMatched, 
            new VerificationWindow(2, 2));
    }
}
```

