## 📚 Context and Examples

**Frontend Token Refresh:**
```typescript
let refreshPromise: Promise<TokenResponse> | null = null;

const refreshAccessToken = async (): Promise<TokenResponse> => {
  // Prevent concurrent refresh requests
  if (refreshPromise) return refreshPromise;

  refreshPromise = (async () => {
    try {
      const refreshToken = localStorage.getItem('refresh_token');

      const response = await fetch('/api/auth/refresh', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken })
      });

      if (!response.ok) {
        // Token invalid/revoked - redirect to login
        localStorage.clear();
        window.location.href = '/login';
        throw new Error('Refresh failed');
      }

      const data = await response.json();

      // Store new tokens
      localStorage.setItem('access_token', data.accessToken);
      localStorage.setItem('refresh_token', data.refreshToken);

      return data;
    } finally {
      refreshPromise = null;
    }
  })();

  return refreshPromise;
};

// Axios interceptor for automatic refresh
axios.interceptors.response.use(
  response => response,
  async error => {
    const originalRequest = error.config;

    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      await refreshAccessToken();

      // Retry original request with new token
      originalRequest.headers.Authorization = 
        `Bearer ${localStorage.getItem('access_token')}`;

      return axios(originalRequest);
    }

    return Promise.reject(error);
  }
);
```

**Token Family Revocation:**
```csharp
public async Task RevokeTokenFamilyAsync(RefreshToken token)
{
    var family = new List<RefreshToken>();

    // Find root token
    var root = token;
    while (root.ParentTokenId != null)
    {
        root = await _context.RefreshTokens
            .FindAsync(root.ParentTokenId.Value);
    }

    // Collect all descendants
    await CollectTokenFamilyAsync(root.Id, family);

    // Revoke all tokens in family
    foreach (var t in family)
    {
        t.RevokedAt = DateTime.UtcNow;
        t.RevokedByIp = _httpContext.Connection.RemoteIpAddress?.ToString();
    }

    await _context.SaveChangesAsync();

    // Log security event
    _logger.LogWarning(
        "Token family revoked for user {UserId}. " +
        "Reuse detected at {RevokedAt}",
        token.UserId, DateTime.UtcNow);
}

private async Task CollectTokenFamilyAsync(
    Guid tokenId, 
    List<RefreshToken> family)
{
    var token = await _context.RefreshTokens.FindAsync(tokenId);
    if (token != null)
    {
        family.Add(token);

        // Find children
        var children = await _context.RefreshTokens
            .Where(t => t.ParentTokenId == tokenId)
            .ToListAsync();

        foreach (var child in children)
        {
            await CollectTokenFamilyAsync(child.Id, family);
        }
    }
}
```

