**Anomaly Detection:**
```csharp
public class SessionAnomalyDetector
{
    public async Task<SessionRiskScore> AnalyzeSessionAsync(
        SessionTracking session, 
        List<SessionTracking> userSessions)
    {
        var risks = new List<Risk>();

        // Check geo-velocity
        var recentSession = userSessions
            .Where(s => s.CreatedAt > DateTime.UtcNow.AddHours(-2))
            .OrderByDescending(s => s.CreatedAt)
            .FirstOrDefault();

        if (recentSession != null)
        {
            var distance = CalculateDistance(
                recentSession.Location, 
                session.Location);
            var timeDiff = (session.CreatedAt - recentSession.CreatedAt)
                .TotalHours;
            var speed = distance / timeDiff; // km/h

            if (speed > 1000) // Impossible travel
            {
                risks.Add(new Risk
                {
                    Type = RiskType.ImpossibleTravel,
                    Severity = RiskSeverity.High,
                    Description = "Login from location impossible to reach"
                });
            }
        }

        // Check for concurrent sessions from different countries
        var concurrentCountries = userSessions
            .Where(s => !s.IsRevoked)
            .Select(s => s.Location)
            .Distinct()
            .Count();

        if (concurrentCountries > 2)
        {
            risks.Add(new Risk
            {
                Type = RiskType.MultipleCountries,
                Severity = RiskSeverity.Medium,
                Description = "Active sessions in multiple countries"
            });
        }

        return new SessionRiskScore
        {
            Score = CalculateScore(risks),
            Risks = risks
        };
    }
}
```

