# Billing Webhook Processing & Event Handling

## Request Type
Feature Request

## User Story
As a **SaaS platform**, I want to **reliably process webhooks from payment gateways and billing providers** so that I can **keep subscription and payment states synchronized, handle asynchronous events, and ensure data consistency**.

## Problem Statement
Payment gateways and billing providers send critical events via webhooks:
- Payment succeeded/failed notifications
- Subscription state changes (trial ended, renewed, canceled)
- Dispute notifications (chargeback initiated/resolved)
- Invoice finalized/paid notifications
- Payment method updates (card expiration, update via Account Updater)

Without proper webhook handling:
- Subscription states become out of sync
- Failed payments aren't retried promptly
- Customer disputes are missed
- Manual reconciliation required
- Customer experience suffers (access not granted despite payment)

## Proposed Solution
Implement a robust webhook processing system with verification, idempotency, and reliable event handling:

### WebhookEvent Entity
```csharp
public class WebhookEvent : EntityBase<Guid>
{
    // Source
    public string Provider { get; set; } // "stripe", "paypal", etc.
    public string EventId { get; set; } // Gateway's event ID
    public string EventType { get; set; } // "payment.succeeded", "invoice.paid"

    // Payload
    public string RawPayload { get; set; } // Original JSON
    public DateTime ReceivedAt { get; set; }

    // Processing
    public WebhookStatus Status { get; set; }
    public int ProcessingAttempts { get; set; }
    public DateTime? ProcessedAt { get; set; }
    public DateTime? LastAttemptAt { get; set; }
    public DateTime? NextRetryAt { get; set; }

    // Verification
    public string Signature { get; set; }
    public bool SignatureVerified { get; set; }
    public DateTime? VerifiedAt { get; set; }

    // Results
    public string? ProcessingError { get; set; }
    public Dictionary<string, string>? ProcessingResult { get; set; }

    // Related Entities
    public Guid? TenantId { get; set; }
    public Guid? PaymentId { get; set; }
    public Guid? SubscriptionId { get; set; }
    public Guid? InvoiceId { get; set; }

    // Metadata
    public string IpAddress { get; set; }
    public string UserAgent { get; set; }
    public Dictionary<string, string> Headers { get; set; }
}

public enum WebhookStatus
{
    Received,
    Verified,
    Processing,
    Processed,
    Failed,
    Ignored
}
```

### Webhook Handler Interface
```csharp
public interface IWebhookHandler
{
    string Provider { get; }

    Task<WebhookVerificationResult> VerifySignatureAsync(
        string payload,
        IDictionary<string, string> headers,
        string secret);

    Task<WebhookProcessingResult> ProcessEventAsync(
        WebhookEvent webhookEvent);

    bool CanHandle(string eventType);
}

public abstract class WebhookHandlerBase : IWebhookHandler
{
    public abstract string Provider { get; }

    public abstract Task<WebhookVerificationResult> VerifySignatureAsync(
        string payload,
        IDictionary<string, string> headers,
        string secret);

    public abstract bool CanHandle(string eventType);

    public async Task<WebhookProcessingResult> ProcessEventAsync(
        WebhookEvent webhookEvent)
    {
        // Idempotency check
        if (await IsAlreadyProcessedAsync(webhookEvent.EventId))
            return WebhookProcessingResult.AlreadyProcessed();

        // Parse and route to specific handler
        var eventType = ParseEventType(webhookEvent.RawPayload);

        return eventType switch
        {
            "payment.succeeded" => await HandlePaymentSucceededAsync(webhookEvent),
            "payment.failed" => await HandlePaymentFailedAsync(webhookEvent),
            "subscription.updated" => await HandleSubscriptionUpdatedAsync(webhookEvent),
            "subscription.deleted" => await HandleSubscriptionDeletedAsync(webhookEvent),
            "invoice.paid" => await HandleInvoicePaidAsync(webhookEvent),
            "invoice.payment_failed" => await HandleInvoicePaymentFailedAsync(webhookEvent),
            "customer.subscription.trial_will_end" => await HandleTrialWillEndAsync(webhookEvent),
            "charge.dispute.created" => await HandleDisputeCreatedAsync(webhookEvent),
            _ => WebhookProcessingResult.Ignored($"Unhandled event type: {eventType}")
        };
    }

    protected abstract Task<WebhookProcessingResult> HandlePaymentSucceededAsync(WebhookEvent webhookEvent);
    protected abstract Task<WebhookProcessingResult> HandlePaymentFailedAsync(WebhookEvent webhookEvent);
    // ... other handlers
}
```

### Stripe Webhook Handler
```csharp
public class StripeWebhookHandler : WebhookHandlerBase
{
    private readonly IPaymentService _paymentService;
    private readonly ISubscriptionService _subscriptionService;
    private readonly IInvoiceService _invoiceService;

    public override string Provider => "stripe";

    public override async Task<WebhookVerificationResult> VerifySignatureAsync(
        string payload,
        IDictionary<string, string> headers,
        string secret)
    {
        try
        {
            var signature = headers["Stripe-Signature"];
            var stripeEvent = EventUtility.ConstructEvent(
                payload,
                signature,
                secret);

            return WebhookVerificationResult.Success(stripeEvent.Id);
        }
        catch (StripeException ex)
        {
            return WebhookVerificationResult.Failed(ex.Message);
        }
    }

    protected override async Task<WebhookProcessingResult> HandlePaymentSucceededAsync(
        WebhookEvent webhookEvent)
    {
        var stripeEvent = JsonSerializer.Deserialize<Event>(webhookEvent.RawPayload);
        var paymentIntent = stripeEvent.Data.Object as PaymentIntent;

        // Update payment status
        var payment = await _paymentService.GetByGatewayTransactionIdAsync(paymentIntent.Id);
        if (payment == null)
            return WebhookProcessingResult.Failed("Payment not found");

        await _paymentService.MarkAsSucceededAsync(
            payment.Id,
            paymentIntent.Charges.Data[0].Id);

        // Update subscription if applicable
        if (payment.SubscriptionId.HasValue)
        {
            await _subscriptionService.ActivateAsync(payment.SubscriptionId.Value);
        }

        // Mark invoice as paid
        if (payment.InvoiceId.HasValue)
        {
            await _invoiceService.MarkAsPaidAsync(
                payment.InvoiceId.Value,
                payment.Id);
        }

        return WebhookProcessingResult.Success(new Dictionary<string, string>
        {
            ["PaymentId"] = payment.Id.ToString(),
            ["Status"] = "Succeeded"
        });
    }

    protected override async Task<WebhookProcessingResult> HandleSubscriptionUpdatedAsync(
        WebhookEvent webhookEvent)
    {
        var stripeEvent = JsonSerializer.Deserialize<Event>(webhookEvent.RawPayload);
        var subscription = stripeEvent.Data.Object as Subscription;

        var localSub = await _subscriptionService
            .GetByGatewaySubscriptionIdAsync(subscription.Id);

        if (localSub == null)
            return WebhookProcessingResult.Failed("Subscription not found");

        // Sync status
        await _subscriptionService.SyncStatusFromGatewayAsync(
            localSub.Id,
            subscription.Status,
            subscription.CurrentPeriodEnd);

        return WebhookProcessingResult.Success();
    }
}
