### Webhook Processing Service
```csharp
public class WebhookProcessingService : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await ProcessPendingWebhooksAsync();
            await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
        }
    }

    private async Task ProcessPendingWebhooksAsync()
    {
        var pendingWebhooks = await _webhookRepo
            .GetPendingForProcessingAsync(limit: 50);

        foreach (var webhook in pendingWebhooks)
        {
            await ProcessWebhookAsync(webhook);
        }
    }

    private async Task ProcessWebhookAsync(WebhookEvent webhook)
    {
        try
        {
            webhook.Status = WebhookStatus.Processing;
            webhook.LastAttemptAt = DateTime.UtcNow;
            webhook.ProcessingAttempts++;
            await _webhookRepo.UpdateAsync(webhook);

            var handler = _handlers.FirstOrDefault(h => 
                h.Provider == webhook.Provider && 
                h.CanHandle(webhook.EventType));

            if (handler == null)
            {
                webhook.Status = WebhookStatus.Ignored;
                webhook.ProcessingError = "No handler found";
                await _webhookRepo.UpdateAsync(webhook);
                return;
            }

            var result = await handler.ProcessEventAsync(webhook);

            if (result.IsSuccess)
            {
                webhook.Status = WebhookStatus.Processed;
                webhook.ProcessedAt = DateTime.UtcNow;
                webhook.ProcessingResult = result.Data;
            }
            else
            {
                webhook.Status = WebhookStatus.Failed;
                webhook.ProcessingError = result.Error;
                webhook.NextRetryAt = CalculateNextRetry(webhook.ProcessingAttempts);
            }

            await _webhookRepo.UpdateAsync(webhook);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Webhook processing failed for {WebhookId}", webhook.Id);

            webhook.Status = WebhookStatus.Failed;
            webhook.ProcessingError = ex.Message;
            webhook.NextRetryAt = CalculateNextRetry(webhook.ProcessingAttempts);
            await _webhookRepo.UpdateAsync(webhook);
        }
    }

    private DateTime CalculateNextRetry(int attempts)
    {
        // Exponential backoff: 1min, 5min, 15min, 1hr, 6hr
        var delays = new[] { 1, 5, 15, 60, 360 };
        var delayMinutes = attempts < delays.Length 
            ? delays[attempts] 
            : 1440; // 24 hours

        return DateTime.UtcNow.AddMinutes(delayMinutes);
    }
}
