### FraudDetectionService Implementation
```csharp
public class FraudDetectionService : IFraudDetectionService
{
    private readonly ApplicationDbContext _context;
    private readonly ILogger<FraudDetectionService> _logger;

    public async Task<FraudScore> ScorePaymentAsync(Guid paymentId, CancellationToken cancellationToken)
    {
        var payment = await _context.Payments
            .Include(p => p.User)
            .Include(p => p.PaymentMethod)
            .FirstOrDefaultAsync(p => p.Id == paymentId, cancellationToken);

        if (payment == null)
            throw new NotFoundException($"Payment {paymentId} not found");

        var signals = new List<FraudSignal>();
        decimal totalScore = 0;

        // Rule 1: Velocity Check (multiple payments in 10 minutes)
        var recentPayments = await _context.Payments
            .Where(p => p.UserId == payment.UserId && 
                       p.CreatedAt >= DateTime.UtcNow.AddMinutes(-10))
            .CountAsync(cancellationToken);

        if (recentPayments > 3)
        {
            var velocityScore = Math.Min((recentPayments - 3) * 15, 40);
            signals.Add(new FraudSignal
            {
                SignalType = "VelocityCheck",
                Weight = velocityScore,
                Details = JsonSerializer.Serialize(new { PaymentCount = recentPayments, WindowMinutes = 10 }),
                DetectedAt = DateTime.UtcNow
            });
            totalScore += velocityScore;
        }

        // Rule 2: IP Country Mismatch
        var userCountry = payment.User.Country;
        var ipCountry = await GetCountryFromIPAsync(payment.IpAddress);
        if (userCountry != ipCountry && !string.IsNullOrEmpty(userCountry))
        {
            signals.Add(new FraudSignal
            {
                SignalType = "IPCountryMismatch",
                Weight = 20,
                Details = JsonSerializer.Serialize(new { UserCountry = userCountry, IPCountry = ipCountry }),
                DetectedAt = DateTime.UtcNow
            });
            totalScore += 20;
        }

        // Rule 3: Card BIN Check
        var cardBin = payment.PaymentMethod.CardNumber?.Substring(0, 6);
        var binCountry = await GetCountryFromBINAsync(cardBin);
        if (binCountry != userCountry && !string.IsNullOrEmpty(binCountry) && !string.IsNullOrEmpty(userCountry))
        {
            signals.Add(new FraudSignal
            {
                SignalType = "BINMismatch",
                Weight = 25,
                Details = JsonSerializer.Serialize(new { CardCountry = binCountry, UserCountry = userCountry }),
                DetectedAt = DateTime.UtcNow
            });
            totalScore += 25;
        }

        // Rule 4: Disposable Email
        if (IsDisposableEmail(payment.User.Email))
        {
            signals.Add(new FraudSignal
            {
                SignalType = "DisposableEmail",
                Weight = 30,
                Details = JsonSerializer.Serialize(new { Email = payment.User.Email }),
                DetectedAt = DateTime.UtcNow
            });
            totalScore += 30;
        }

        // Rule 5: New Account + High Value
        var accountAgeHours = (DateTime.UtcNow - payment.User.CreatedAt).TotalHours;
        if (accountAgeHours < 24 && payment.Amount > 500)
        {
            signals.Add(new FraudSignal
            {
                SignalType = "NewAccountHighValue",
                Weight = 35,
                Details = JsonSerializer.Serialize(new { AccountAgeHours = accountAgeHours, Amount = payment.Amount }),
                DetectedAt = DateTime.UtcNow
            });
            totalScore += 35;
        }

        // Rule 6: Card Testing Pattern (small amount)
        if (payment.Amount < 5)
        {
            var smallTransactions = await _context.Payments
                .Where(p => p.IpAddress == payment.IpAddress &&
                           p.Amount < 5 &&
                           p.CreatedAt >= DateTime.UtcNow.AddMinutes(-30))
                .CountAsync(cancellationToken);

            if (smallTransactions > 5)
            {
                signals.Add(new FraudSignal
                {
                    SignalType = "CardTestingPattern",
                    Weight = 50,
                    Details = JsonSerializer.Serialize(new { SmallTransactions = smallTransactions, Amount = payment.Amount }),
                    DetectedAt = DateTime.UtcNow
                });
                totalScore += 50;
            }
        }

        // Cap total score at 100
        totalScore = Math.Min(totalScore, 100);

        // Determine risk level and decision
        var riskLevel = totalScore switch
        {
            < 30 => FraudRiskLevel.Low,
            < 60 => FraudRiskLevel.Medium,
            < 85 => FraudRiskLevel.High,
            _ => FraudRiskLevel.Critical
        };

        var decision = totalScore switch
        {
            < 60 => FraudDecision.Allow,
            < 85 => FraudDecision.Review,
            _ => FraudDecision.Block
        };

        var fraudScore = new FraudScore
        {
            PaymentId = paymentId,
            UserId = payment.UserId,
            Score = totalScore,
            RiskLevel = riskLevel,
            Decision = decision,
            DecisionReason = $"{signals.Count} fraud signals detected",
            Signals = signals,
            ActionTaken = decision == FraudDecision.Block ? FraudAction.Blocked : FraudAction.None,
            ScoredAt = DateTime.UtcNow
        };

        await _context.FraudScores.AddAsync(fraudScore, cancellationToken);
        await _context.SaveChangesAsync(cancellationToken);

        _logger.LogWarning("Payment {PaymentId} scored {Score}/100 - Risk: {RiskLevel}, Decision: {Decision}",
            paymentId, totalScore, riskLevel, decision);

        return fraudScore;
    }

    private bool IsDisposableEmail(string email)
    {
        var disposableDomains = new[] { "mailinator.com", "guerrillamail.com", "10minutemail.com", "temp-mail.org" };
        var domain = email.Split('@').LastOrDefault()?.ToLowerInvariant();
        return disposableDomains.Contains(domain);
    }
}
```

