## Technical Requirements

### Database Schema
```sql
CREATE TABLE FraudScores (
    Id UUID PRIMARY KEY,
    UserId UUID NULL,
    PaymentId UUID NULL,
    SubscriptionId UUID NULL,
    Score DECIMAL(5, 2) NOT NULL CHECK (Score >= 0 AND Score <= 100),
    RiskLevel VARCHAR(20) NOT NULL,
    Decision VARCHAR(20) NOT NULL,
    DecisionReason TEXT NOT NULL,
    Signals JSONB NOT NULL,
    ActionTaken VARCHAR(50) NOT NULL,
    ScoredAt TIMESTAMP NOT NULL,
    IsManuallyReviewed BOOLEAN NOT NULL DEFAULT false,
    ReviewNotes TEXT NULL,
    ReviewedByUserId UUID NULL,
    ReviewedAt TIMESTAMP NULL,
    INDEX idx_payment (PaymentId),
    INDEX idx_user_risk (UserId, ScoredAt DESC),
    INDEX idx_pending_review (Decision, IsManuallyReviewed) WHERE Decision = 'Review' AND IsManuallyReviewed = false,
    FOREIGN KEY (UserId) REFERENCES Users(Id),
    FOREIGN KEY (PaymentId) REFERENCES Payments(Id),
    FOREIGN KEY (SubscriptionId) REFERENCES Subscriptions(Id)
);

CREATE TABLE FraudRules (
    Id UUID PRIMARY KEY,
    RuleName VARCHAR(100) NOT NULL UNIQUE,
    RuleType VARCHAR(50) NOT NULL,
    IsEnabled BOOLEAN NOT NULL DEFAULT true,
    BaseScore DECIMAL(5, 2) NOT NULL,
    Configuration JSONB NOT NULL,
    Priority INT NOT NULL,
    CreatedAt TIMESTAMP NOT NULL DEFAULT NOW(),
    UpdatedAt TIMESTAMP NULL
);

CREATE TABLE IPBlacklist (
    Id UUID PRIMARY KEY,
    IpAddress VARCHAR(45) NOT NULL UNIQUE,
    Reason TEXT NOT NULL,
    AddedAt TIMESTAMP NOT NULL DEFAULT NOW(),
    ExpiryDate TIMESTAMP NULL,
    INDEX idx_expiry (ExpiryDate) WHERE ExpiryDate IS NOT NULL
);
```

