### ReferralService Implementation
```csharp
public class ReferralService : IReferralService
{
    private readonly ApplicationDbContext _context;
    private readonly ICreditService _creditService;
    private readonly INotificationService _notificationService;

    public async Task<Result<string>> GenerateReferralCodeAsync(Guid userId, CancellationToken cancellationToken)
    {
        // Check if user already has referral code
        var existing = await _context.Referrals
            .Where(r => r.ReferrerUserId == userId)
            .Select(r => r.ReferralCode)
            .FirstOrDefaultAsync(cancellationToken);

        if (existing != null)
            return Result<string>.Success(existing);

        // Generate unique code
        var code = GenerateUniqueCode(userId);
        var link = $"https://yourapp.com/signup?ref={code}";

        // Create initial referral record
        var referral = new Referral
        {
            ReferrerUserId = userId,
            ReferralCode = code,
            ReferralLink = link,
            SharedAt = DateTime.UtcNow,
            Status = ReferralStatus.Pending
        };

        await _context.Referrals.AddAsync(referral, cancellationToken);
        await _context.SaveChangesAsync(cancellationToken);

        return Result<string>.Success(code);
    }

    public async Task<Result<Referral>> TrackReferralConversionAsync(
        Guid userId, 
        Guid subscriptionId,
        CancellationToken cancellationToken)
    {
        // Find referral for this user
        var referral = await _context.Referrals
            .Include(r => r.Program)
            .FirstOrDefaultAsync(r => r.RefereeUserId == userId && 
                                     r.Status == ReferralStatus.SignedUp,
                                cancellationToken);

        if (referral == null)
            return Result<Referral>.Failure("No referral found for user");

        // Update referral status
        referral.Status = ReferralStatus.Converted;
        referral.ConversionAt = DateTime.UtcNow;
        referral.RefereeSubscriptionId = subscriptionId;

        await _context.SaveChangesAsync(cancellationToken);

        // Issue rewards
        if (referral.Program.RequirePayment)
        {
            await IssueReferralRewardsAsync(referral.Id, cancellationToken);
        }

        return Result<Referral>.Success(referral);
    }

    public async Task<Result> IssueReferralRewardsAsync(Guid referralId, CancellationToken cancellationToken)
    {
        var referral = await _context.Referrals
            .Include(r => r.Program)
            .Include(r => r.Referrer)
            .FirstOrDefaultAsync(r => r.Id == referralId, cancellationToken);

        if (referral == null)
            return Result.Failure("Referral not found");

        if (referral.Status != ReferralStatus.Converted)
            return Result.Failure("Referral not converted yet");

        var program = referral.Program;

        // Issue referrer reward
        if (program.ReferrerRewardType == ReferralRewardType.AccountCredit)
        {
            var credit = await _creditService.IssueCreditsAsync(
                referral.ReferrerUserId,
                program.ReferrerRewardValue,
                "USD",
                CreditType.General,
                $"Referral: {referral.RefereeEmail}",
                cancellationToken);

            referral.ReferrerRewardId = credit.Value.Id;
        }

        // Issue referee reward
        if (referral.RefereeUserId.HasValue && program.RefereeRewardType == ReferralRewardType.AccountCredit)
        {
            var credit = await _creditService.IssueCreditsAsync(
                referral.RefereeUserId.Value,
                program.RefereeRewardValue,
                "USD",
                CreditType.General,
                $"Referral from: {referral.Referrer.Email}",
                cancellationToken);

            referral.RefereeRewardId = credit.Value.Id;
        }

        referral.Status = ReferralStatus.RewardIssued;
        referral.RewardIssuedAt = DateTime.UtcNow;

        // Update program totals
        program.TotalReferrals++;
        program.TotalRewardsIssued += program.ReferrerRewardValue + program.RefereeRewardValue;

        await _context.SaveChangesAsync(cancellationToken);

        // Notify both parties
        await _notificationService.SendAsync(new NotificationRequest
        {
            UserId = referral.ReferrerUserId,
            Type = NotificationType.ReferralRewardIssued,
            Subject = "You earned a referral reward!",
            Body = $"Thanks for referring {referral.RefereeEmail}! You've earned {program.ReferrerRewardValue:C}."
        }, cancellationToken);

        return Result.Success();
    }

    private string GenerateUniqueCode(Guid userId)
    {
        // Generate memorable 8-character code: XXXX-YYYY
        var random = new Random(userId.GetHashCode());
        const string chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // Avoid confusing chars
        var code = new string(Enumerable.Range(0, 8)
            .Select(_ => chars[random.Next(chars.Length)])
            .ToArray());
        return $"{code.Substring(0, 4)}-{code.Substring(4)}";
    }
}
```

