### Smart Routing Engine
```csharp
public class PaymentRoutingEngine
{
    public async Task<IPaymentGateway> SelectGatewayAsync(
        PaymentRoutingContext context)
    {
        var eligibleGateways = await GetEligibleGatewaysAsync(context);

        if (!eligibleGateways.Any())
            throw new NoEligibleGatewayException();

        // Apply routing strategy
        return context.RoutingStrategy switch
        {
            RoutingStrategy.Priority => 
                eligibleGateways.OrderBy(g => g.Priority).First(),
            RoutingStrategy.LowestCost => 
                eligibleGateways.OrderBy(g => CalculateCost(g, context)).First(),
            RoutingStrategy.BestPerformance => 
                eligibleGateways.OrderByDescending(g => g.SuccessRate).First(),
            RoutingStrategy.Geographic => 
                SelectByGeography(eligibleGateways, context.Country),
            RoutingStrategy.LoadBalancing => 
                SelectByLoadBalancing(eligibleGateways),
            _ => eligibleGateways.First()
        };
    }

    private async Task<List<GatewayConfiguration>> GetEligibleGatewaysAsync(
        PaymentRoutingContext context)
    {
        return await _gatewayRepo.GetAllAsync()
            .Where(g => g.IsEnabled)
            .Where(g => g.SupportedCurrencies.Contains(context.Currency))
            .Where(g => g.SupportedCountries.Contains(context.Country))
            .Where(g => g.SupportedPaymentMethods.Contains(context.PaymentMethodType))
            .Where(g => context.Amount >= g.MinTransactionAmount 
                     && context.Amount <= g.MaxTransactionAmount)
            .ToListAsync();
    }
}

public class PaymentRoutingContext
{
    public decimal Amount { get; set; }
    public string Currency { get; set; }
    public string Country { get; set; }
    public PaymentMethodType PaymentMethodType { get; set; }
    public RoutingStrategy RoutingStrategy { get; set; }
    public Guid? CustomerId { get; set; }
}

public enum RoutingStrategy
{
    Priority,        // Use highest priority gateway
    LowestCost,      // Minimize transaction fees
    BestPerformance, // Highest success rate
    Geographic,      // Best for customer region
    LoadBalancing    // Distribute across gateways
}
```

### Failover Logic
```csharp
public class PaymentProcessor
{
    private readonly PaymentRoutingEngine _routingEngine;
    private readonly IEnumerable<IPaymentGateway> _gateways;

    public async Task<Result<PaymentResult>> ProcessPaymentAsync(
        PaymentRequest request)
    {
        var context = CreateRoutingContext(request);
        var attemptedGateways = new List<string>();

        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                var gateway = await _routingEngine.SelectGatewayAsync(context);

                if (attemptedGateways.Contains(gateway.GatewayId))
                    continue; // Already tried this gateway

                attemptedGateways.Add(gateway.GatewayId);

                var result = await gateway.ChargeAsync(new ChargeRequest
                {
                    Amount = request.Amount,
                    Currency = request.Currency,
                    PaymentMethodId = request.PaymentMethodId,
                    Description = request.Description
                });

                if (result.IsSuccess)
                {
                    await RecordSuccessMetricsAsync(gateway.GatewayId);
                    return result;
                }

                if (!result.Error.IsRetriable)
                    return result;

                await RecordFailureMetricsAsync(gateway.GatewayId, result.Error);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, 
                    "Gateway failure on attempt {Attempt}", attempt + 1);

                if (attempt == 2)
                    throw;
            }
        }

        return Result<PaymentResult>.Failure(
            "All payment gateways failed after 3 attempts");
    }
}
```

