### Payment Retry Strategy
```csharp
public class PaymentRetryStrategy
{
    // Smart retry schedule based on failure type
    public static Dictionary<string, int[]> RetrySchedules = new()
    {
        // Days to wait between retries
        ["card_declined"] = new[] { 1, 3, 5, 7 },
        ["insufficient_funds"] = new[] { 3, 7, 14 },
        ["expired_card"] = new[] { 0 }, // No retry, card must be updated
        ["do_not_honor"] = new[] { 1, 7 },
        ["processing_error"] = new[] { 0, 1, 2, 3 },
        ["default"] = new[] { 1, 3, 7, 14 }
    };

    public static DateTime CalculateNextRetry(
        string failureCode,
        int currentRetryCount)
    {
        var schedule = RetrySchedules.ContainsKey(failureCode)
            ? RetrySchedules[failureCode]
            : RetrySchedules["default"];

        if (currentRetryCount >= schedule.Length)
            return DateTime.MaxValue; // No more retries

        return DateTime.UtcNow.AddDays(schedule[currentRetryCount]);
    }
}
```

