### PricingEngine Implementation
```csharp
public class PricingEngine : IPricingEngine
{
    private readonly ApplicationDbContext _context;
    private readonly IDiscountService _discountService;
    private readonly ITaxCalculationService _taxService;
    private readonly ICreditService _creditService;
    private readonly ILogger<PricingEngine> _logger;

    public async Task<PriceCalculationResult> CalculatePriceAsync(
        PriceCalculationRequest request, 
        CancellationToken cancellationToken)
    {
        var result = new PriceCalculationResult
        {
            CalculationId = Guid.NewGuid(),
            CalculatedAt = DateTime.UtcNow,
            Currency = request.Currency
        };

        var explanation = new StringBuilder();

        // Step 1: Get base plan price
        if (request.PlanId.HasValue)
        {
            var plan = await _context.Plans.FindAsync(request.PlanId.Value);
            var pricing = await GetPlanPricingAsync(plan, request.Currency, request.BillingInterval ?? BillingInterval.Monthly);
            result.BasePlanPrice = pricing.Amount;
            explanation.AppendLine($"Base plan: {plan.Name} = {pricing.Amount:C}");
        }
        else if (request.BaseAmount.HasValue)
        {
            result.BasePlanPrice = request.BaseAmount.Value;
            explanation.AppendLine($"Custom amount = {request.BaseAmount.Value:C}");
        }

        // Step 2: Add addons
        if (request.AddonIds?.Any() == true)
        {
            foreach (var addonId in request.AddonIds)
            {
                var addon = await _context.Addons.FindAsync(addonId);
                var addonPrice = addon.GetPriceForCurrency(request.Currency);
                result.AddonsTotal += addonPrice;
                explanation.AppendLine($"  + Addon: {addon.Name} = {addonPrice:C}");
            }
        }

        // Step 3: Calculate usage charges
        if (request.UsageQuantities?.Any() == true)
        {
            foreach (var (metricName, quantity) in request.UsageQuantities)
            {
                var metric = await _context.UsageMetrics
                    .FirstOrDefaultAsync(m => m.Name == metricName, cancellationToken);

                var charge = CalculateTieredUsage(metric, quantity);
                result.UsageCharges += charge;
                explanation.AppendLine($"  + Usage: {metricName} x {quantity} = {charge:C}");
            }
        }

        result.Subtotal = result.BasePlanPrice + result.AddonsTotal + result.UsageCharges;
        explanation.AppendLine($"Subtotal = {result.Subtotal:C}");

        // Step 4: Apply discounts (ordered by priority)
        if (request.PromoCodes?.Any() == true)
        {
            var discounts = await EvaluateDiscountsAsync(
                result.Subtotal, 
                request.PromoCodes, 
                request.UserId,
                cancellationToken);

            decimal runningSubtotal = result.Subtotal;

            foreach (var discount in discounts.OrderBy(d => d.Priority))
            {
                var discountAmount = CalculateDiscountAmount(discount, runningSubtotal);

                discount.AppliedTo = runningSubtotal;
                discount.AmountDiscounted = discountAmount;
                result.AppliedDiscounts.Add(discount);
                result.TotalDiscounts += discountAmount;

                runningSubtotal -= discountAmount;

                explanation.AppendLine($"  - Discount: {discount.Code} ({discount.Type}) = -{discountAmount:C}");

                // Check if stackable
                if (!discount.IsStackable)
                    break;
            }
        }

        result.SubtotalAfterDiscounts = result.Subtotal - result.TotalDiscounts;

        // Step 5: Proration adjustment
        if (request.Proration.HasValue && request.ProrationStartDate.HasValue && request.ProrationEndDate.HasValue)
        {
            var proration = CalculateProration(
                result.SubtotalAfterDiscounts,
                request.ProrationStartDate.Value,
                request.ProrationEndDate.Value,
                request.BillingInterval ?? BillingInterval.Monthly);

            result.Proration = proration;
            result.ProrationAdjustment = proration.Adjustment;
            explanation.AppendLine($"Proration ({proration.DaysUsed}/{proration.TotalDays} days) = {proration.Adjustment:C}");
        }

        var taxableAmount = result.SubtotalAfterDiscounts + result.ProrationAdjustment;

        // Step 6: Calculate tax
        if (request.IncludeTax && request.TaxInfo != null)
        {
            var taxResult = await _taxService.CalculateTaxAsync(new TaxCalculationRequest
            {
                Amount = taxableAmount,
                Currency = request.Currency,
                CountryCode = request.TaxInfo.CountryCode,
                StateCode = request.TaxInfo.StateCode,
                PostalCode = request.TaxInfo.PostalCode,
                TaxId = request.TaxInfo.TaxId,
                IsBusinessPurchase = request.TaxInfo.IsBusinessPurchase
            }, cancellationToken);

            result.Tax = taxResult;
            result.TaxAmount = taxResult.TaxAmount;
            explanation.AppendLine($"  + Tax ({taxResult.TaxRate * 100:F2}%) = {taxResult.TaxAmount:C}");
        }

        result.Total = taxableAmount + result.TaxAmount;

        // Step 7: Apply credits
        if (request.ApplyCredits && request.UserId.HasValue)
        {
            var availableCredits = await _creditService.GetAvailableCreditsAsync(
                request.UserId.Value, 
                request.Currency,
                cancellationToken);

            var creditsToApply = Math.Min(
                availableCredits,
                request.MaxCreditUsage ?? availableCredits,
                result.Total
            );

            if (creditsToApply > 0)
            {
                result.Credits = new CreditApplicationResult
                {
                    CreditsAvailable = availableCredits,
                    CreditsApplied = creditsToApply,
                    RemainingCredits = availableCredits - creditsToApply
                };
                result.CreditsApplied = creditsToApply;
                explanation.AppendLine($"  - Credits applied = -{creditsToApply:C}");
            }
        }

        result.AmountDue = result.Total - result.CreditsApplied;
        explanation.AppendLine($"Amount Due = {result.AmountDue:C}");

        result.CalculationExplanation = explanation.ToString();

        // Store calculation for audit trail
        await StorePriceCalculationAsync(result, request, cancellationToken);

        return result;
    }

    private decimal CalculateTieredUsage(UsageMetric metric, decimal quantity)
    {
        decimal total = 0;
        decimal remaining = quantity;

        foreach (var tier in metric.Tiers.OrderBy(t => t.StartQuantity))
        {
            if (remaining <= 0) break;

            var tierQuantity = tier.EndQuantity.HasValue 
                ? Math.Min(remaining, tier.EndQuantity.Value - tier.StartQuantity)
                : remaining;

            total += tierQuantity * tier.PricePerUnit;
            remaining -= tierQuantity;
        }

        return total;
    }

    private decimal CalculateDiscountAmount(AppliedDiscount discount, decimal appliedTo)
    {
        return discount.Type switch
        {
            DiscountType.Percentage => appliedTo * (discount.Value / 100m),
            DiscountType.FixedAmount => Math.Min(discount.Value, appliedTo),
            DiscountType.Credits => 0, // Credits applied separately
            _ => 0
        };
    }

    private ProrationDetails CalculateProration(
        decimal amount, 
        DateTime startDate, 
        DateTime endDate, 
        BillingInterval interval)
    {
        var totalDays = interval switch
        {
            BillingInterval.Monthly => 30,
            BillingInterval.Yearly => 365,
            _ => 30
        };

        var daysUsed = (endDate - startDate).Days;
        var dailyRate = amount / totalDays;
        var proratedAmount = dailyRate * daysUsed;

        return new ProrationDetails
        {
            TotalDays = totalDays,
            DaysUsed = daysUsed,
            DailyRate = dailyRate,
            Adjustment = proratedAmount - amount
        };
    }
}
