### Discount Stacking Engine
```csharp
public class DiscountStackingEngine
{
    public DiscountCalculationResult CalculateDiscount(
        decimal baseAmount,
        List<PromoCode> promoCodes,
        DiscountStackingRules rules)
    {
        var result = new DiscountCalculationResult
        {
            OriginalAmount = baseAmount,
            FinalAmount = baseAmount
        };

        // Sort by priority
        var sortedCodes = promoCodes
            .Where(c => c.IsActive && IsValid(c))
            .OrderByDescending(c => c.Priority)
            .ToList();

        // Apply stacking rules
        var applicableCodes = FilterByStackingRules(sortedCodes, rules);

        foreach (var code in applicableCodes)
        {
            var discount = CalculateSingleDiscount(
                result.FinalAmount,
                code);

            result.AppliedDiscounts.Add(new AppliedDiscount
            {
                PromoCodeId = code.Id,
                Code = code.Code,
                DiscountAmount = discount,
                Type = code.Type
            });

            result.FinalAmount -= discount;
        }

        result.TotalDiscount = result.OriginalAmount - result.FinalAmount;
        return result;
    }
}
```

