### Refund Processing Service
```csharp
public class RefundProcessingService
{
    public async Task<Result> ProcessRefundAsync(Guid refundId)
    {
        var refund = await _refundRepo.GetByIdAsync(refundId);

        if (refund.Status != RefundStatus.Approved)
            return Result.Failure("Refund not approved");

        refund.Status = RefundStatus.Processing;
        await _refundRepo.UpdateAsync(refund);

        try
        {
            var payment = await _paymentRepo.GetByIdAsync(refund.PaymentId);
            var gateway = _gatewayFactory.GetGateway(payment.GatewayName);

            var result = await gateway.RefundAsync(new RefundRequest
            {
                TransactionId = payment.GatewayTransactionId,
                Amount = refund.Amount,
                Currency = refund.Currency,
                Reason = refund.Reason.ToString()
            });

            if (result.IsSuccess)
            {
                refund.Status = RefundStatus.Succeeded;
                refund.ProcessedAt = DateTime.UtcNow;
                refund.GatewayRefundId = result.Value.RefundId;

                // Credit wallet if applicable
                if (refund.Type == RefundType.Partial)
                {
                    await _walletService.AddFundsAsync(
                        refund.TenantId,
                        refund.Amount,
                        TransactionReason.Refund,
                        $"Refund for payment {payment.Id}",
                        refund.Id);
                }

                // Update payment
                payment.RefundedAmount += refund.Amount;
                payment.Status = payment.RefundedAmount == payment.Amount 
                    ? PaymentStatus.Refunded 
                    : PaymentStatus.PartiallyRefunded;
                await _paymentRepo.UpdateAsync(payment);

                // Send notification
                await _notificationService.SendRefundSuccessNotificationAsync(refund);

                return Result.Success();
            }
            else
            {
                refund.Status = RefundStatus.Failed;
                refund.FailedAt = DateTime.UtcNow;
                refund.FailureReason = result.Error.Message;
                refund.RetryCount++;

                await _refundRepo.UpdateAsync(refund);

                return Result.Failure(result.Error.Message);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Refund processing failed for {RefundId}", refundId);
            refund.Status = RefundStatus.Failed;
            refund.FailureReason = ex.Message;
            await _refundRepo.UpdateAsync(refund);
            throw;
        }
    }
}
```

